import datetime
from functools import lru_cache
from calendar import monthrange

_DIGITS = frozenset("0123456789")
_MAX_YEAR = 3000


def _is_digit(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _range_bounds(s, lo, hi):
    parts = s.split("-")
    if len(parts) != 2 or not _is_digit(parts[0]) or not _is_digit(parts[1]):
        raise ValueError("invalid range")
    a = int(parts[0])
    b = int(parts[1])
    if a > b:
        raise ValueError("range start greater than range end")
    if a < lo or b > hi:
        raise ValueError("value out of range")
    return a, b


def _add_value(values, value, lo, hi, is_dow):
    if value < lo or value > hi:
        raise ValueError("value out of range")
    if is_dow:
        # Cron: 0/7 = Sunday, 1 = Monday, ..., 6 = Saturday.
        # Python weekday(): Monday = 0, ..., Sunday = 6.
        values.add((value - 1) % 7)
    else:
        values.add(value)


def _add_item(item, lo, hi, is_dow, values):
    if item == "*":
        for v in range(lo, hi + 1):
            _add_value(values, v, lo, hi, is_dow)
        return

    if "/" in item:
        base, sep, step_s = item.partition("/")
        if not sep or "/" in step_s:
            raise ValueError("invalid item")
        if not _is_digit(step_s):
            raise ValueError("invalid step")
        step = int(step_s)
        if step == 0:
            raise ValueError("step must be at least 1")

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            start, end = _range_bounds(base, lo, hi)
        else:
            raise ValueError("step requires a range or *")

        for v in range(start, end + 1, step):
            _add_value(values, v, lo, hi, is_dow)
        return

    if "-" in item:
        start, end = _range_bounds(item, lo, hi)
        for v in range(start, end + 1):
            _add_value(values, v, lo, hi, is_dow)
        return

    if not _is_digit(item):
        raise ValueError("invalid item")
    _add_value(values, int(item), lo, hi, is_dow)


def _parse_field(s, lo, hi, is_dow=False):
    is_star = s == "*"
    values = set()

    for item in s.split(","):
        if item == "":
            raise ValueError("empty item")
        _add_item(item, lo, hi, is_dow, values)

    if not values:
        raise ValueError("empty field")

    mask = 0
    if is_dow:
        # values are already Python weekday numbers 0..6
        for v in values:
            mask |= 1 << v
    else:
        for v in values:
            mask |= 1 << (v - lo)

    return mask, values, is_star


@lru_cache(maxsize=None)
def _get_spec(expr):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    minute_mask, _, _ = _parse_field(fields[0], 0, 59)
    hour_mask, _, _ = _parse_field(fields[1], 0, 23)
    dom_mask, _, dom_star = _parse_field(fields[2], 1, 31)
    month_mask, _, _ = _parse_field(fields[3], 1, 12)
    _, dow_values, dow_star = _parse_field(fields[4], 0, 7, is_dow=True)

    if not month_mask:
        raise ValueError("cron expression can never fire")

    # The only structural impossibility, besides invalid field values, is
    # an impossible day-of-month restriction when day-of-week is unrestricted.
    if not dom_star and dow_star:
        max_days = (31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
        mm = month_mask
        possible = False
        while mm:
            bit = mm & -mm
            month = bit.bit_length()  # 1-based month number
            if dom_mask & ((1 << max_days[month - 1]) - 1):
                possible = True
                break
            mm ^= bit
        if not possible:
            raise ValueError("cron expression can never fire")

    if dow_star:
        dow_masks = None
    else:
        dow_bits = 0
        for v in dow_values:
            dow_bits |= 1 << v

        masks = []
        for first_weekday in range(7):
            mask = 0
            for off in range(31):
                if (dow_bits >> ((first_weekday + off) % 7)) & 1:
                    mask |= 1 << off
            masks.append(mask)
        dow_masks = tuple(masks)

    first_hour = (hour_mask & -hour_mask).bit_length() - 1
    first_minute = (minute_mask & -minute_mask).bit_length() - 1
    first_month = (month_mask & -month_mask).bit_length()

    return (
        minute_mask,
        hour_mask,
        dom_mask,
        month_mask,
        dom_star,
        dow_star,
        dow_masks,
        first_hour,
        first_minute,
        first_month,
    )


def _next_time(hour_mask, minute_mask, hour, minute, first_minute):
    # Same hour, minute >= requested minute.
    if hour_mask & (1 << hour):
        cand = minute_mask & (~((1 << minute) - 1))
        if cand:
            return hour, (cand & -cand).bit_length() - 1

    # Otherwise, the earliest later allowed hour with its earliest minute.
    later_hours = hour_mask & (~((1 << (hour + 1)) - 1))
    if later_hours:
        return (later_hours & -later_hours).bit_length() - 1, first_minute

    return None


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    (
        minute_mask,
        hour_mask,
        dom_mask,
        month_mask,
        dom_star,
        dow_star,
        dow_masks,
        first_hour,
        first_minute,
        first_month,
    ) = _get_spec(expr)

    # First minute boundary strictly later than `after`.
    start = after.replace(second=0, microsecond=0)
    if start <= after:
        start += datetime.timedelta(minutes=1)

    sy, sm, sd = start.year, start.month, start.day
    sh, smin = start.hour, start.minute

    y, m, d = sy, sm, sd

    while y < _MAX_YEAR:
        # Skip to the next allowed month if the current month is not allowed.
        if not ((month_mask >> (m - 1)) & 1):
            later_months = month_mask & (~((1 << m) - 1))
            if later_months:
                m = (later_months & -later_months).bit_length()
                d = 1
                continue

            y += 1
            if y >= _MAX_YEAR:
                break
            m = first_month
            d = 1
            continue

        first_weekday, last_day = monthrange(y, m)
        if d > last_day:
            d = 1

        days_bits = (1 << last_day) - 1

        # Traditional cron day matching.
        if dom_star:
            if dow_star:
                allowed_days = days_bits
            else:
                allowed_days = dow_masks[first_weekday] & days_bits
        else:
            dom_part = dom_mask & days_bits
            if dow_star:
                allowed_days = dom_part
            else:
                allowed_days = dom_part | (dow_masks[first_weekday] & days_bits)

        if not allowed_days:
            m += 1
            if m == 13:
                m = 1
                y += 1
            d = 1
            continue

        if d <= last_day:
            lower_bits = ((1 << (last_day - d + 1)) - 1) << (d - 1)
            candidate_bits = allowed_days & lower_bits

            if candidate_bits:
                day = (candidate_bits & -candidate_bits).bit_length()  # 1-based day

                if y == sy and m == sm and day == sd:
                    t = _next_time(hour_mask, minute_mask, sh, smin, first_minute)
                    if t is not None:
                        return datetime.datetime(y, m, day, t[0], t[1])

                    # No valid time remains today; continue from tomorrow.
                    d = day + 1
                    if d > last_day:
                        m += 1
                        if m == 13:
                            m = 1
                            y += 1
                        d = 1
                    continue

                # Any later date is fine, so use the earliest time on that day.
                return datetime.datetime(y, m, day, first_hour, first_minute)

        # No valid day in this month at or after `d`.
        m += 1
        if m == 13:
            m = 1
            y += 1
        d = 1

    raise ValueError("cron expression can never fire")
